 "content": "def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # Find opposite edge markers, and fill each seed's row/column from the
    # marker edge to the seed; seed changes to 4.
    bg=max(set(v for row in g for v in row), key=lambda v:sum(row.count(v) for row in g))
    frame=next(v for v in set(v for row in g for v in row) if v!=bg and sum(row[0]==v for row in g)>=2 and sum(row[-1]==v for row in g)>=2)
    left=[r for r in range(h) if g[r][0]==frame]
    right=[r for r in range(h) if g[r][-1]==frame]
    seeds=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (bg,frame)]
    for r,c,col in seeds:
        # row is one of the boundary bands; each point shoots horizontally
        if r in left:
            for x in range(1,c): g[r][x]=col
            g[r][c]=4
            t=min(right)+(r-min(left))
            if t in right:
                for x in range(1,w-1):g[t][x]=col
        elif r in right:
            for x in range(c+1,w-1):g[r][x]=col
            g[r][c]=4
            t=min(left)+(r-min(right))
            if t in left:
                for x in range(1,w-1):g[t][x]=col
        else:
            # Unique interior seed sends a line perpendicular to boundary
            for y in range(max(left+right)+1,h):
                if g[y][c]==bg: g[y][c]=col
            g[r][c]=4
            # continue upward from first edge band when appropriate
            if r>max(left+right):
                for y in max(left+right)+1:r:
                    if g[y][c]==bg:g[y][c]=col
            elif r<min(left+right):
                for y in r+1:min(left+right):
                    if g[y][c]==bg:g[y][c]=col
    return g
